// RoomAsset.swift — PRTS Arknights base-room render (天镜阁会客堂 reception hall),
// fetched from prts.wiki furniture data, quantized and base64-embedded. Used as the
// screensaver backdrop. See tools/bake-operator/ for the fetch approach.

import CoreGraphics
import Foundation
import ImageIO

enum RoomAsset {
    nonisolated(unsafe) static let receptionHall: CGImage? = decode(b64)

    private static func decode(_ s: String) -> CGImage? {
        guard let d = Data(base64Encoded: s),
              let src = CGImageSourceCreateWithData(d as CFData, nil),
              let img = CGImageSourceCreateImageAtIndex(src, 0, nil) else { return nil }
        return img
    }

    private static let b64 = [
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        ""
    ].joined()
}
